ON CONFLICT ("techId", "date") DO UPDATE SET
  "startTime" = EXCLUDED."startTime",
  "finishTime" = EXCLUDED."finishTime",
  "minutesLate" = EXCLUDED."minutesLate",
  "hrsWorked" = EXCLUDED."hrsWorked",
  "status" = EXCLUDED."status",
  "routeStartTime" = EXCLUDED."routeStartTime",
  "updatedAt" = NOW();
